window.registerChapter({"num": 35, "source_label": "35", "title": "Thermal Environment of the Intensive Care Nursery", "group": "NICU environment & monitoring", "features": ["Prematurity", "Cardiac shunting", "Infection / inflammation", "Jaundice / cholestasis", "Encephalopathy", "Feeding difficulty", "Electrolyte / acid–base", "Skin findings", "Maternal / placental factors", "Family / comfort"], "pdf_start": 605, "pdf_end": 614, "printed_start": "594", "printed_end": "603", "figures": [{"path": "figures/ch035_p0606_vector_35_1.jpg", "caption": "• Fig. 35.1 Heat exchange through evaporation in relation to gestational age. Measurements from the first day of life during incubator care at an ambient humidity of 50%. (Data from Hammarlund K, Sedin G. Transepidermal water loss in newborn infants. VI. Heat exchange with the environment in relation to gestational age. Acta Paediatr Scand. 1982;71[2]:191–196.)", "caption_matched": true, "caption_match_method": "Caption identified in source; vector crop boundaries estimated automatically", "pdf_page": 606, "printed_page": "595", "chapter": 35, "image_type": "vector-diagram render", "bounds_review": "automatic; consult preserved source-page view"}, {"path": "figures/ch035_p0607_vector_35_2.jpg", "caption": "• Fig. 35.2 Heat exchange in relation to postnatal age in different gestational age groups. (Data from Hammarlund K, Sedin G. Heat loss from the skin of preterm and full-term newborn infants during the first weeks after birth. Biol Neonate. 1986;50[1]:1–10.)", "caption_matched": true, "caption_match_method": "Caption identified in source; vector crop boundaries estimated automatically", "pdf_page": 607, "printed_page": "596", "chapter": 35, "image_type": "vector-diagram render", "bounds_review": "automatic; consult preserved source-page view"}, {"path": "figures/ch035_p0607_vector_35_3.jpg", "caption": "• Fig. 35.3 The main components of the homeostatic thermoregulatory system.", "caption_matched": true, "caption_match_method": "Caption identified in source; vector crop boundaries estimated automatically", "pdf_page": 607, "printed_page": "596", "chapter": 35, "image_type": "vector-diagram render", "bounds_review": "automatic; consult preserved source-page view"}, {"path": "figures/ch035_p0608_vector_35_4.jpg", "caption": "• Fig. 35.4 The ranges of environmental temperatures needed to provide warmth for infants weighing 1 to 3 kg at birth in draft-free, uniform-temperature surroundings at 50% relative humidity. Upper curves represent naked infants, and lower curves represent swaddled, “cot-nursed” babies. Thick lines represent “thermoneutral” temperature, and shaded areas represent the range within which the infant can maintain normal temperature without increasing heat production or evaporative heat loss by more than 25%. (From Hey EN. The care of babies in incubators. In: Gairdner D, et al, eds. Recent Advances in Paediatrics. 4th ed. London: Churchill Livingstone; 1971.)", "caption_matched": true, "caption_match_method": "Caption identified in source; vector crop boundaries estimated automatically", "pdf_page": 608, "printed_page": "597", "chapter": 35, "image_type": "vector-diagram render", "bounds_review": "automatic; consult preserved source-page view"}, {"path": "figures/ch035_p0611_vector_35_5.jpg", "caption": "• Fig. 35.5 Skin temperatures (Tskin) in a group of extremely (22- to 26-week) preterm infants during early (first week) skin-to-skin care (SSC). Tskin was measured in the incubator before SSC (pre), during SSC, and after return to the incubator (post). (Data from Karlsson V, Heinemann AB, Sjörs G, et al. Early skin-to-skin care in extremely preterm infants: thermal balance and care environment. J Pediatr. 2012;161[3]:422–426.)", "caption_matched": true, "caption_match_method": "Caption identified in source; vector crop boundaries estimated automatically", "pdf_page": 611, "printed_page": "600", "chapter": 35, "image_type": "vector-diagram render", "bounds_review": "automatic; consult preserved source-page view"}], "tables": [{"path": "tables/ch035_p0607_1.jpg", "markdown": "|Col1|Col2|Col3|\n|---|---|---|\n||||\n||||\n\n", "pdf_page": 607, "printed_page": "596", "orientation_normalized": false}, {"path": "tables/ch035_p0608_1.jpg", "markdown": "|Col1|36<br>32<br>28<br>24<br>20<br>Birth weight 1 kg<br>16|Col3|Col4|36<br>32<br>28<br>24<br>20<br>Birth weight 2 kg<br>16|Col6|Col7|Naked<br>Cot nursed<br>Birth weight 3 kg|Col9|Col10|Col11|\n|---|---|---|---|---|---|---|---|---|---|---|\n||Birth weight 1 kg<br>28<br>32<br>36<br>24<br>20<br>16|Birth weight 1 kg<br>28<br>32<br>36<br>24<br>20<br>16|Birth weight 1 kg<br>28<br>32<br>36<br>24<br>20<br>16|Birth weight 2 kg<br>28<br>32<br>36<br>24<br>20<br>16|Birth weight 2 kg<br>28<br>32<br>36<br>24<br>20<br>16|Birth weight 2 kg<br>28<br>32<br>36<br>24<br>20<br>16|Birth weight 3 kg<br>Naked<br>Cot nursed|Birth weight 3 kg<br>Naked<br>Cot nursed|Birth weight 3 kg<br>Naked<br>Cot nursed||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n||||||||||||\n\n", "pdf_page": 608, "printed_page": "597", "orientation_normalized": false}], "cards": 6, "summary": "Convection, radiation, evaporation and conduction. All four heat-exchange modes vary with maturity, environment and postnatal age.", "pillars": [{"label": "Heat-exchange modes", "text": "Convection, radiation, evaporation and conduction. All four heat-exchange modes vary with maturity, environment and postnatal age.", "pdf_page": 605, "printed_page": "594"}, {"label": "Immature skin", "text": "An immature skin barrier. Skin barrier competence develops with maturity, so very immature infants have much higher transepidermal water and heat loss.", "pdf_page": 605, "printed_page": "594"}, {"label": "Thermoneutrality", "text": "The range allowing normal temperature at minimal metabolic rate using nonevaporative adjustments. Thermoneutrality includes metabolic efficiency; a normal temperature alone does not prove it.", "pdf_page": 607, "printed_page": "596"}, {"label": "Humidity and evaporation", "text": "Increase appropriate incubator humidity. Higher humidity lowers evaporative loss and can aid fluid and heat balance in very immature infants.", "pdf_page": 610, "printed_page": "599"}, {"label": "Servo-control failure", "text": "Overwarming from inappropriate heat delivery. A detached probe can lead to overwarming; device readings must be interpreted alongside infant assessment.", "pdf_page": 610, "printed_page": "599"}], "reader_html": "<section class=\"source-section\" data-pdf-page=\"605\"><h2>PDF page 605 · Printed 594</h2><h3>Overview</h3><p>35 Thermal Environment of</p><small class=\"source\">PDF p. 605</small><p>the Intensive Care Nursery</p><small class=\"source\">PDF p. 605</small><h3>Johan Ågren</h3><p>Thermal management of the newborn infant is a cornerstone of neonatal care. The field accommodates important advances in care provision, from pioneering studies on chronic cold stress1 and neonatal incubation to kangaroo mother care,2 prevention of low admission temperatures,3 and therapeutic hypothermia. Globally, cold stress remains a contributor to neonatal mortality and morbidity, and the potential impact of optimal thermal care provision on infant health is huge.4 A basic understanding of the physics and physiology of heat exchange enables the undertaking of adequate measures to reduce heat loss and monitor body temperature, measures that are often simple and easy to apply. Without thermal care, a term 5-kg newborn may quickly and easily become hypothermic, increasing its need for endogenous heat production and posing a risk for cardiorespiratory instability and failure to feed properly, states that may be detrimental to an otherwise healthy or only slightly depressed infant. On the other hand, with adequate preparation, equipment, and training, the body temperature of a 500-g extremely preterm infant can be kept within the normal range, aiding a smooth transition to extrauterine life. In general, adequate thermal management depends at least as much on sound knowledge as on the use of high-tech devices such as incubators and radiant warmers.</p><small class=\"source\">PDF p. 605</small><h3>The Four Modes Of Heat Exchange</h3><p>Direct heat exchange between the infant and its environment occurs through the skin and the respiratory tract. With the use of different techniques, this heat exchange has been estimated with reasonable accuracy.5,6 The four modes of heat exchange—convection, radiation, evaporation, and conduction (Box 35.1)—all influence thermal balance, and the relative contribution of each mode changes with maturity, postnatal age, disease state, and care environment. Analysis of the contribution from the different modes of heat exchange makes it straightforward to reduce heat loss</p><small class=\"source\">PDF p. 605</small><p>in any given situation, minimizing the need for delivery of heat through another route. Together with proper temperature monitoring, such an approach simplifies thermal management and renders individual estimates of heat loss unnecessary in clinical practice.</p><small class=\"source\">PDF p. 605</small><h3>Heat Exchange At Term Birth</h3><p>The wet newborn infant will be exposed to moving air and surfaces that have a much lower temperature than that in utero. Unless the infant is wiped dry and covered by a blanket, heat loss through evaporation and radiation to surrounding surfaces of the delivery room will be high and lead to rapid cooling. Heat loss through convection is also significant unless airflow velocity is reduced (e.g., by covering or clothing). As soon as the term or moderately preterm infant is dry, radiant heat loss will dominate.</p><small class=\"source\">PDF p. 605</small><h3>Evaporative Heat Loss Is Related To Infant Maturity And Ambient Humidity</h3><p>As loss of fluid also implies loss of heat, evaporative fluid loss is an important component of heat exchange, particularly in extremely preterm infants. A functionally competent skin barrier develops gradually during fetal life.7 Consequently, the magnitude of water loss through the skin is related to maturity at birth,8 and the tiniest infants may have evaporative heat losses that are many times higher than those of a term infant under similar environmental conditions (Fig. 35.1).9,10 In the preterm infant, relatively rapid postnatal skin maturation occurs, leading to decreased evaporative loss over the first postnatal days and weeks (Fig. 35.2).11 This maturation explains the gradual reduction in the environmental temperature needed to obtain thermal balance, even though evaporative heat loss still exceeds radiant heat loss for about a week in the most immature infants (see Fig. 35.2).</p><small class=\"source\">PDF p. 605</small><p>Evaporative heat losses are inversely related to ambient humidity12 and measures to increase the vapor pressure close to the skin thus simplify fluid and thermal management in the most immature infants.10 Note that the impact</p><small class=\"source\">PDF p. 605</small></section><section class=\"source-section\" data-pdf-page=\"606\"><h2>PDF page 606 · Printed 595</h2><h3>• Box 35.1 The Modes Of Heat Exchange</h3><p>Convection</p><small class=\"source\">PDF p. 606</small><p>• Air movement causes warm air close to the skin to move</p><small class=\"source\">PDF p. 606</small><p>away, resulting in heat loss. • The relative magnitude of heat loss through convection is</p><small class=\"source\">PDF p. 606</small><p>similar in term and preterm infants. • Convective heat loss is much increased when air velocity is</p><small class=\"source\">PDF p. 606</small><p>high (forced convection). • Convective heating is the mode by which modern intensive</p><small class=\"source\">PDF p. 606</small><p>care incubators operate. • Convective heat exchange is reduced by any measure that</p><small class=\"source\">PDF p. 606</small><p>will minimize air movement close to the skin (e.g., limiting incubator porthole opening to one side at a time, providing clothing and/or blankets).</p><small class=\"source\">PDF p. 606</small><p>Radiation</p><small class=\"source\">PDF p. 606</small><p>• Radiant heat transfer occurs from the infant to surrounding</p><small class=\"source\">PDF p. 606</small><p>cooler surfaces and to the infant from radiant heaters and warm-light phototherapy devices. • The magnitude of heat exchange depends on the</p><small class=\"source\">PDF p. 606</small><p>temperatures of the surfaces facing the infant and on the body surface area exposed. • Heat radiation is reduced by clothes, blankets, double</p><small class=\"source\">PDF p. 606</small><p>incubator walls, heat shields, flexible plastic wrap, and bags.</p><small class=\"source\">PDF p. 606</small><p>Evaporation</p><small class=\"source\">PDF p. 606</small><p>• Evaporation of fluid from the skin surface implies loss of</p><small class=\"source\">PDF p. 606</small><p>heat (approximately 2.4 kJ/g of water). • Evaporation is the dominant route for heat loss from</p><small class=\"source\">PDF p. 606</small><p>the wet neonate in the delivery room but is substantially reduced by immediately wiping the infant dry at birth. • Very immature infants have poor skin barrier function,</p><small class=\"source\">PDF p. 606</small><p>leading to large ongoing losses of water and heat for several days to weeks after birth. • Evaporation is reduced in a high-vapor-pressure</p><small class=\"source\">PDF p. 606</small><p>environment.</p><small class=\"source\">PDF p. 606</small><p>Conduction</p><small class=\"source\">PDF p. 606</small><p>• Inadvertent conductive heat loss is negligible in most care</p><small class=\"source\">PDF p. 606</small><p>situations because mattresses used in incubators and cots are made of insulating material. • Care must be taken when using equipment with an active</p><small class=\"source\">PDF p. 606</small><p>warming function. If switched off, a gel mattress such as those used in some radiant warmer beds and/or an unheated water-filled mattress will be a very effective conductive cooler for any size neonate. • Conductive cooling is the method by which all systems for</p><small class=\"source\">PDF p. 606</small><p>hypothermia treatment operate. • Conductive heat delivery (e.g., heated mattress or skin-to-</p><small class=\"source\">PDF p. 606</small><p>skin care) is a simple and effective way to rewarm infants and stabilize body temperature.</p><small class=\"source\">PDF p. 606</small><p>of postnatal age and ambient humidity on evaporative loss is less clinically important in newborn infants with a gestational age of more than 28 to 30 weeks and in extremely preterm infants beyond the first postnatal week.</p><small class=\"source\">PDF p. 606</small><h3>Respiratory Loss Of Heat</h3><p>Respiratory water and heat exchange take place through the combined processes of evaporation and convection. These</p><small class=\"source\">PDF p. 606</small><h3>• Fig. 35.1 Heat Exchange Through Evaporation In Relation To Gesta-</h3><p>processes occur because the temperature and vapor pressure of the inspired air rapidly equilibrate in the airway. Consequently, the losses are related to air temperature and humidity and directly proportional to the rate of breathing. The provision of a warm and humid environment (e.g., humidified incubator) and/or assisted ventilation with the use of adequately warmed and humidified (saturated at ≥37.0° C) gas will reduce respiratory loss of water and heat to a minimum and aid temperature stability.6 Only in situations in which cold (pressurized) gas is delivered will the heat loss through the airway be of clinical significance.</p><small class=\"source\">PDF p. 606</small><h3>The Fetal Thermal Equilibrium</h3><p>The fetus generates heat in the processes of tissue proliferation, metabolism, maintenance of physiologic functions, and muscular movement. From experimental studies, fetal (and neonatal) heat production per unit weight has been demonstrated to be considerably higher than in the adult. Together with heat generated by the uterus and placenta, this results in a temperature gradient between the fetus and the mother of about 0.5° C, with the heat being dissipated mainly via the placental circulation.13</p><small class=\"source\">PDF p. 606</small><h3>Neonatal Thermoregulation</h3><p>The exposure to cold, the clamping of the umbilical cord, and the general “stress of being born” induce a thermal response. This response is part of a homeostatic system with</p><small class=\"source\">PDF p. 606</small><figure class=\"source-page\"><a href=\"tables/ch035_page0606.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch035_page0606.jpg\" alt=\"Original source page 606, including its figures or tables\"></a><figcaption>Original source-page view · PDF 606. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"607\"><h2>PDF page 607 · Printed 596</h2><h3>Neonatal Thermoregulation</h3><p>input (detectors) and output (effectors) that is aimed at preserving body temperature. The main components are schematically depicted in Fig. 35.3.</p><small class=\"source\">PDF p. 607</small><p>In the neonate, shivering thermogenesis is nonoperative in the normal to near-normal body temperature range, and a cold-exposed infant thus depends primarily on chemical thermogenesis to avoid hypothermia. Exposure to cold induces a sympathetic surge that acts on receptors in brown fat stores, stimulating lipolysis. The presence of the protein thermogenin in brown fat uncouples beta-oxidation, resulting in metabolic production of heat instead of adenosine triphosphate. The metabolic rate of a newborn has been observed to increase up to threefold when maximally stimulated by cold,14 but preterm infants have a limited thermogenic capacity caused by scarce fat stores and, at times, suboptimal nutritional provision.</p><small class=\"source\">PDF p. 607</small><p>The cost of heat production implies that even a slight long-term exposure to cold will increase thermogenesis, consume oxygen and substrate stores, and impact negatively on growth.</p><small class=\"source\">PDF p. 607</small><h3>Thermoneutrality</h3><p>The concept of an optimum thermal environment for newborn infants evolved during the 1960s.15 This “thermoneutral zone” (Fig. 35.4) is defined as the range of temperature within which the infant can maintain a normal body temperature at a minimal metabolic rate with the use of nonevaporative processes (vasoconstriction, vasodilation, and/ or changes in posture) only. Body size has a large impact on the range in which infants can maintain body temperature. Compared with an adult, the newborn infant has both a several times higher body surface per mass ratio and a poorly insulated body shell. Several factors related to the care environment will, to a varying extent, influence the boundaries of the thermoneutral zone (Table 35.1). Outside this range,</p><small class=\"source\">PDF p. 607</small><p>body temperature might still be maintained at the cost of an increased metabolism, but if the temperature deviates further, inevitable cooling (or warming) will take place. The temperature ranges for each care modality and individual infant may be crudely estimated, and together with proper infant monitoring, such estimates will suffice as a starting point for routine care.</p><small class=\"source\">PDF p. 607</small><h3>Overwarming Versus Fever</h3><p>Overheating activates heat-losing mechanisms such as skin vasodilation (redness/flushing/peripheral warmth) and behavioral changes (the infant assumes spread-eagle</p><small class=\"source\">PDF p. 607</small><figure class=\"source-page\"><a href=\"tables/ch035_page0607.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch035_page0607.jpg\" alt=\"Original source page 607, including its figures or tables\"></a><figcaption>Original source-page view · PDF 607. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"608\"><h2>PDF page 608 · Printed 597</h2><h3>Overwarming Versus Fever</h3><p>posture). Evaporative heat loss increases, and overt sweating can be noted in a term infant. The gradient between central and peripheral temperature decreases. With severe heat stress, the infant may become hyperactive and irritable.</p><small class=\"source\">PDF p. 608</small><p>In contrast, an infant with fever because of an increase in endogenous heat production presents differently. The febrile infant, at least during the phase of rising temperature, is vasoconstricted as displayed by an increased central-toperipheral temperature gradient and pale-blue–appearing extremities.</p><small class=\"source\">PDF p. 608</small><h3>Hypothermia</h3><p>Different thresholds of the effector response for nonshivering and shivering thermogenesis explain the differences observed between hypothermic adults and neonates. In the range of normal to near-normal body temperature (≥36° C), shivering thermogenesis will be nonoperative in the neonate, and chemical thermogenesis will dominate. However, as the core temperature is further lowered, shivering may occur. Thus shivering is exclusively (and not always) seen in the severely cold-stressed (e.g., hypothermia-treated) infant. Therapeutic hypothermia treatment for neuroprotection in neonatal encephalopathy is discussed elsewhere (see Chapter 56), but the methods used are based on conductive heat loss from either the head (cooling cap) or the whole body (cooling mattress). During therapeutic hypothermia, core temperature has to be monitored because surface temperatures will not adequately reflect core temperature. During cooling, significant set point displacement may occur, explaining why some infants are difficult to warm with the risk of temperature overshoot during rewarming. Therefore the infant’s body temperature needs to be carefully</p><small class=\"source\">PDF p. 608</small><figure class=\"source-page\"><a href=\"tables/ch035_page0608.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch035_page0608.jpg\" alt=\"Original source page 608, including its figures or tables\"></a><figcaption>Original source-page view · PDF 608. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"609\"><h2>PDF page 609 · Printed 598</h2><h3>Hypothermia</h3><p>monitored and controlled for several days after discontinuation of the hypothermia treatment. Data obtained from the cooling trials support the notion that it is better to slowly (maximal rate of 0.5° C/h) increase the core temperature in a hypothermic infant. It seems reasonable to apply similar caution also when rewarming infants who have become hypothermic from other causes, although the optimal speed of rewarming has not been identified.</p><small class=\"source\">PDF p. 609</small><h3>Temperature Monitoring</h3><p>Temperature measurements as such do not provide much information on whether the infant is in thermal balance, and there are no methods suitable for routine bedside monitoring of metabolic rate. Therefore thermal management needs to be based on several sources of information. They include (but are not limited to) trends of continuous or intermittent measurements of central and peripheral body temperature, ambient temperature, and humidity, as well as the general appearance and behavioral state of the infant.</p><small class=\"source\">PDF p. 609</small><h3>Central (“Core”) Body Temperature</h3><p>Several measurement sites serve as estimates of core body temperature. Direct temperature measurements make use of a probe inserted into a body cavity (e.g., rectum, esophagus) that is central enough to measure a zero temperature gradient versus the body core. Esophageal temperature measurements are technically feasible, represent true core temperature,16 and are well tolerated by the infant. Esophageal temperature monitoring is recommended when very strict thermal monitoring is needed and body surface measurements are unreliable (i.e., during therapeutic hypothermia). A thermistor integrated in the feeding tube would be a near-ideal way to monitor temperature in preterm infants. Rectal temperature measurements do not reliably reflect core temperature and pose unnecessary risks of repeated trauma to the rectal mucosa, so their use should be limited.</p><small class=\"source\">PDF p. 609</small><p>Core temperature can also be estimated from indirect temperature measurements at the body surface by artificial creation of zero temperature gradient, or “zero-heat-flux.” By insulation of the measurement probe from the environment, zero-heat-flux will be created between the body core and the probe. Trunk skin temperature measurements (back to mattress, abdomen to mattress, abdomen to insulated pad) rely on this principle and give readings that are very similar to core temperature. Axillary temperature also makes use of zero-heat-flux (insulated by the arm and shoulder) and can be used as a proxy for core temperature when intermittent measurement is deemed sufficient, but it may be associated with infant discomfort and occasionally differ from esophageal temperature.</p><small class=\"source\">PDF p. 609</small><h3>What Temperature Should Be Aimed For?</h3><p>The concept of an easily defined hypothalamic set point for core temperature is relative. Because not only core but</p><small class=\"source\">PDF p. 609</small><p>also peripheral sensory input influences the action of thermoregulation, the optimal core body temperature may indeed vary with maturity/age, care environment, and disease state. Deflections in the set point occur with pyrogen exposure but may also result from exposure to a cold and/ or warm environment, even for a relatively limited time. Normal human central body temperature is considered to be 37.0 ± 0.5° C, and this is probably also true for the newborn infant.17 However, it is evident that seemingly well babies with central temperature kept within this range may still be subjected to cold stress (i.e., display increased metabolic rate because of thermogenesis). Thus aiming for such a “normal” body temperature might at times be suboptimal in neonatal care. In parallel with the fetal thermal equilibrium and to minimize the risk of cold stress when caring for infants with limited thermoregulatory capacity, it might indeed be adequate to aim for slightly higher core temperatures.18</p><small class=\"source\">PDF p. 609</small><h3>Peripheral Temperature And Central- Peripheral Temperature Difference</h3><p>Although not considered integral to routine thermal care, peripheral temperature measurements from the sole of the foot might provide additional and valuable information about the thermal state of the infant, particularly if graphed together with core temperature. Cold exposure induces vasoconstriction and a decrease in skin temperature, resulting in an increased central-to-peripheral temperature difference (ΔT), well before a drop in central temperature occurs. Likewise, other causes of vasoconstriction (hypovolemia, sepsis, catecholamine administration) and low cardiac output (hypovolemia, large ductal shunting, and some congenital heart defects) increase ΔT, which could potentially be of value as an early warning sign.19 However, the optimal ΔT depends on infant maturity, postnatal age, and care environment and is therefore not easily defined. Recommended ΔT for very low birth weight and extremely low birth weight infants nursed in incubators are available (Table 35.2).20</p><small class=\"source\">PDF p. 609</small><h3>Convective Thermal Support—Incubator Care</h3><p>In a modern convectively heated incubator, the warm air is directed so that the walls of the incubator are also kept warm. With a low airflow velocity (&lt;0.1 m/s), the convective heat transfer will depend on the gradient between the skin and the air temperature, and the vapor pressure gradient close to the skin will be maintained, avoiding an increased evaporative heat loss. The feature of a double-wall design reduces the radiant heat loss to the inner walls of the incubator. In a single-wall incubator, the “working” temperature in the incubator will be lower than the set air temperature because of the higher radiant loss of heat and thus will require a higher temperature setting, depending on the room temperature. The incubator is controlled thermostatically by air</p><small class=\"source\">PDF p. 609</small><figure class=\"source-page\"><a href=\"tables/ch035_page0609.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch035_page0609.jpg\" alt=\"Original source page 609, including its figures or tables\"></a><figcaption>Original source-page view · PDF 609. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"610\"><h2>PDF page 610 · Printed 599</h2><h3>Convective Thermal Support—Incubator Care</h3><p>or infant temperature, two modes with distinct advantages and disadvantages.21</p><small class=\"source\">PDF p. 610</small><p>Infant skin temperature servo control has the advantage of providing a more stable body temperature under changing care conditions. However, if the probe becomes detached, this may lead to overwarming, although usually this is not severe. Also, when using skin servo control, the use of body temperature as a possible signal of disease (hypovolemia, sepsis) has to be replaced by monitoring incubator temperature, which might not be as intuitive. An anterior abdominal skin temperature of 36.5° C has been widely used for servo control of incubator air temperature but may be too low to ensure thermoneutrality in the tiniest and most immature infants.20 An abdominal skin (or back to mattress) temperature setting of 37.0° C may then be preferable.</p><small class=\"source\">PDF p. 610</small><p>Air temperature servo control does not require a probe to be attached but makes it necessary to frequently determine infant temperature, thus adding further to the load of procedures disturbing the infants. For both modes, it is essential that procedures such as intravenous line insertion and/ or intubation are performed through the portholes and not through the large front access panel.</p><small class=\"source\">PDF p. 610</small><h3>Incubator Humidification</h3><p>Because evaporative loss is related to ambient relative humidity, adding humidification will decrease heat loss— the higher the humidity, the lower the evaporation. However, in most situations, a higher evaporative loss can be compensated for by a higher air temperature (convective gain), and a “too low” incubator humidity will only increase metabolic demand if the infant is nursed below thermoneutral temperature. Thus a high incubator ambient humidity (70% to 90%) is only vital in situations wherein high insensible water loss per se complicates fluid management (i.e., in extremely preterm infants during the first postnatal week).10,22 In this situation, a high ambient humidity</p><small class=\"source\">PDF p. 610</small><p>is often needed to maintain normal body temperature even at maximal incubator temperature. An increased risk of pseudomonas infections has been demonstrated with the use of incubator humidification23 when condensation of vapor on the inner incubator walls occurs, which therefore should be avoided. Also, experimental studies demonstrate that transepidermal water transport is an important signal for stratum corneum formation,24 and results obtained in extremely preterm infants nursed in incubators at two levels of ambient humidity after the first postnatal week indicate a more rapid barrier formation in infants nursed at a lower relative humidity.25 However, running incubators entirely without humidification will often result in very low humidity (&lt;15% to 20%), promoting large insensible water losses. Although high ambient humidification (70% to 90%) is reserved for the first postnatal week in the extremely preterm (&lt;28 weeks) infant, a medium level of 40% to 50% can be recommended for general incubator care.</p><small class=\"source\">PDF p. 610</small><h3>Radiant Thermal Support—Radiant Warmers</h3><p>Radiant warmers provide excellent accessibility for the care of the newborn infant and have therefore become widely used in neonatal intensive care. The high-power output of the device explains the effectiveness and speed with which a hypothermic infant can be warmed. However, harmful overheating can rapidly occur unless careful monitoring (preferably continuous) of infant temperature is instituted. Because ambient humidity is low and air velocity at times relatively high, heat loss through evaporation and convection may be extensive but can be compensated for by radiant heat gain. An anterior abdominal temperature of 37.0° C is generally recommended for servo control of radiant heat output, at least as a starting point. Unless the warmer is equipped with a warming mattress, the back-to-mattress (zero-heat-flux) temperature can also be used for servo control.</p><small class=\"source\">PDF p. 610</small><p>A transparent heat shield positioned over the infant may influence the heat exchange (occurring through convection, evaporation, and radiation) and result in reduced losses of heat. However, such a shield will also disrupt the servocontrol mechanism and thus may intervene with thermal control. An alternative is the placement of flexible plastic wrap as a blanket loosely over the infant. This method has proved to result in a more homogeneous environment and to reduce insensible water loss and metabolic rate, and it is used in many institutions. Incubators that can interchangeably be used as both radiant warmers and incubators might at times add flexibility of use and improve thermal management of very preterm infants.26,27</p><small class=\"source\">PDF p. 610</small><h3>Conductive Thermal Support—Skin-To-Skin Care</h3><p>Skin-to-skin care (SSC) has been practiced for as long as humanity, long before the concept of kangaroo mother care for preterm infants was introduced. Studies mainly performed in countries with limited resources demonstrate important benefits. In the moderately preterm and low</p><small class=\"source\">PDF p. 610</small><figure class=\"source-page\"><a href=\"tables/ch035_page0610.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch035_page0610.jpg\" alt=\"Original source page 610, including its figures or tables\"></a><figcaption>Original source-page view · PDF 610. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"611\"><h2>PDF page 611 · Printed 600</h2><h3>Conductive Thermal Support—Skin-To-Skin Care</h3><p>birth weight infant, SSC has proven to enhance physiologic stability2 and is recommended.28 Limited guidelines are also available for use in a high-tech setting.29,30 In SSC, the kangaroo position is optimal to enable conductive heat gain through skin-to-skin contact between infant and parent (see also Chapter 36).</p><small class=\"source\">PDF p. 611</small><p>Studies in more immature infants have shown that SSC can be safely applied, and without an increase in metabolic rate, as early as during the first week after birth in stable 28- to 30-week infants and from the second week in infants born at a gestational age of 25 to 27 weeks.31–33</p><small class=\"source\">PDF p. 611</small><p>In another report,34 mechanically ventilated extremely preterm (&lt;26 weeks) infants were studied during early SSC (first week of life), demonstrating that ambient air temperature and humidity are lower during SSC compared with incubator care, thus increasing heat loss through convection, radiation, and evaporation. Transfer from the incubator to SSC results in a drop in temperature, but the conductive heat gain during SSC is sufficient to result in a gradual recovery of the infant’s temperature (Fig. 35.5).</p><small class=\"source\">PDF p. 611</small><h3>Heated Mattresses And Cot Nursing</h3><p>Conductive thermal support may also be provided by the use of a heated mattress. It has been demonstrated that infants as small as 1 kg can be rewarmed and kept warm by placing them on a heated (water-filled) mattress.35 Heated mattresses are most often used in cots for stable, growing preterm infants and are convenient to use interchangeably with SSC. A heated pad can also be used inside incubators or with radiant warmers. Such a mattress should always be prewarmed, and the temperature should never be set lower than the desired body surface temperature; otherwise, this will lead to significant conductive heat loss and may impact negatively on weight gain.</p><small class=\"source\">PDF p. 611</small><h3>Clothing</h3><p>After the immediate postpartum thermal adaptation (30 to 60 minutes), a room temperature of ≥24° C provides a neutral</p><small class=\"source\">PDF p. 611</small><p>thermal environment for a dressed (clothes, cap, and blanket) term neonate. Indeed, clothing can be expected to reduce all modes of heat exchange, and in the relatively stable preterm infant, the use of clothes or a blanket will improve thermal stability during both incubator and radiant warmer care.</p><small class=\"source\">PDF p. 611</small><h3>Phototherapy</h3><p>Open phototherapy increases insensible water loss from the skin of the newborn infant.36 This is mostly an effect of a decrease in relative humidity caused by the increase in ambient temperature, but minute effects have also been demonstrated with cold-light phototherapy.37 Accordingly, the effect is not observed if the infant is treated in an incubator with a controlled environment, and neither fluid nor thermal management should be significantly impacted. In the past decades, flexible and portable “phototherapy blankets” have been made available. Such devices work well with most modes of neonatal care, including incubators, radiant warmers, cot nursing, and SSC.</p><small class=\"source\">PDF p. 611</small><h3>Recommendations For Practice</h3><p>Thermal care benefits from a protocol-driven approach based on guidelines that minimize variation in practice. Such guidelines should specify ranges for normal body and skin temperatures and thermal environment recommendations. They should specify in which situations incubators, radiant warmers, heated mattresses, and SSC are applicable and when to use continuous temperature measurement and infant servo or air control.21 As incubator settings and operation will differ between types of incubators, it is beneficial if the most vulnerable population can be cared for under uniform environmental conditions (same room and incubator type, for instance) within each neonatal unit, and extra caution should be applied when switching to a different mode of care (e.g., from incubator to SSC). The different modes of care each have their advantages and disadvantages, and a combination of incubation, radiant warmer, and SSC is needed to ensure physiologic stability, allow monitoring, and</p><small class=\"source\">PDF p. 611</small><figure class=\"source-page\"><a href=\"tables/ch035_page0611.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch035_page0611.jpg\" alt=\"Original source page 611, including its figures or tables\"></a><figcaption>Original source-page view · PDF 611. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"612\"><h2>PDF page 612 · Printed 601</h2><h3>Recommendations For Practice</h3><p>promote parental involvement. It is not a matter of highversus low-tech care delivery but rather of finding the best compromise and getting the most out of each mode of care.</p><small class=\"source\">PDF p. 612</small><h3>Before Birth</h3><p>The space used for resuscitation should always be ready for instant use. With a prewarmed radiant warmer (and mattress), adequate thermal management of an ill moderately preterm or term neonate is uncomplicated. When needed, the radiant heat output can be instantaneously increased. When available, the heated mattress should be set at 37.0° C. When an extremely preterm infant is awaited, further measures must be undertaken (see Very [28–31 weeks] and Extremely [&lt;28 weeks] Preterm Infants). It is, for many reasons, valuable to meet the parents before delivery, time permitting. Specifically, information about thermal care is relatively easy to grasp even in a stressful situation and can, as such, contribute to a sense of recognition, involvement, and meaningfulness for the parents.</p><small class=\"source\">PDF p. 612</small><h3>Term And Moderate To Late Preterm (&gt;32 Weeks) Infants</h3><p>The vigorous term and near-term infants should be carefully wiped, placed on the mother’s chest, and covered by a cap and blanket. As long as the delivery room temperature is ≥24° C, these measures will usually suffice to provide thermoneutrality. The term infant may then be continuously cared for skin-to-skin and when not, dressed and placed in a cot. If the infant is low birth weight and/or in the lower range of gestational age, uninterrupted conductive heat support, preferably through SSC, is required to maintain thermal balance. If SSC cannot be arranged, the low-birthweight infant must be dressed and placed on a heated mattress or in an incubator. If resuscitation is required, it should be performed under a radiant warmer, and the infant should be placed skin-to-skin with the mother after stabilization.</p><small class=\"source\">PDF p. 612</small><p>Globally, most infants will be born in low-resource settings without access to neonatal care facilities (see Chapter 7). Specifically, thermal care will often have to be provided without high-tech equipment and/or electricity. The principle of wiping the infant dry and establishing continuous skin-to-skin contact with the mother (or other family member) is solid and could, if uniformly applied, be expected to reduce infant mortality.4 If resuscitation is needed, this might be performed without interrupting the skin-to-skin contact or at least by rapidly returning the infant to its natural conductive heat source (i.e., mother) after stabilization.</p><small class=\"source\">PDF p. 612</small><h3>Very (28–31 Weeks) And Extremely (&lt;28 Weeks) Preterm Infants</h3><p>At birth, very preterm infants must be cared for under a radiant warmer, preferably equipped with a heated mattress, to ensure adequate thermal balance. The infant should be wiped and placed on dry linen under the radiant warmer</p><small class=\"source\">PDF p. 612</small><p>for resuscitation and stabilization. In the extremely preterm infant, transepidermal water loss will keep the skin constantly wet. As a consequence, it is not meaningful to dry the infant. This situation is better handled by placing the infant in a transparent plastic bag. This will effectively limit convective heat loss and create a high humidity microclimate close to the skin that will reduce evaporative heat loss.3 Radiant heat will still be transferred from the warmer to the infant’s skin through the plastic bag. This measure has proved to improve thermal care during resuscitation and result in higher NICU admission temperatures. In this vulnerable population, ventilator support should always be provided using humidified gas saturated at body temperature.6 If stabilization takes more than approximately 10 minutes, it is advisable to monitor infant temperature to avoid overwarming. After stabilization, the preterm infant may either be nursed in an incubator or under a radiant warmer. For extremely preterm infants, measures to reduce insensible water and heat loss through the skin are recommended throughout the first week of life. In the incubator, this is accomplished by adding humidification, and under the radiant warmer, by use of a plastic wrap.10 SSC can provide even the tiniest infant with an excellent care environment but needs to be carefully conducted and should be postponed until the end of the first week in the smallest infants.30 For these infants, the room temperature needs to be elevated, preferably to ≥26° C during SSC. The parent should wear an open-front shirt, and the infant should wear a diaper and a cap and be wrapped during the transfer. The infant is placed skin-to-skin in the kangaroo position on the parent’s chest, monitoring is attached (including thermistor for back skin temperature), and the infant is covered by blankets. To minimize cold stress, the sessions of SSC should be at least several hours long to allow the attainment of a stable microenvironment around the infant and stabilize body temperature. As monitoring of back skin temperature under a blanket will not render zero-heat-flux, a back skin temperature of ≥36.5° C during SSC may be considered thermally neutral (author’s unpublished observations). Suggested modes of care and their timing are given in Table 35.3.</p><small class=\"source\">PDF p. 612</small><p>During the first 12 to 24 hours after birth, perturbation of the care environment occurs very frequently. Careful planning and prioritizing among procedures such as weighing, umbilical line insertion, intubation, obtaining chest radiographs, manipulating intravenous lines, repositioning, and suctioning is often helpful, and precautions should be undertaken to prevent heat loss during these procedures.</p><small class=\"source\">PDF p. 612</small><p>With increasing postnatal age and body weight, the temperature requirements of the care environment decrease, and as infant stability improves, there is less need for constant monitoring of the infant. The infant may eventually be dressed and/or covered and transferred from the incubator (or radiant warmer) to a cot with a heated mattress.38 Weaning from the mattress is usually possible at a body weight of approximately 1600 g.38 Thermal stability is an important criterion for discharge, and parents should be advised on how to proceed with thermal care at home.</p><small class=\"source\">PDF p. 612</small><figure class=\"source-page\"><a href=\"tables/ch035_page0612.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch035_page0612.jpg\" alt=\"Original source page 612, including its figures or tables\"></a><figcaption>Original source-page view · PDF 612. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"613\"><h2>PDF page 613 · Printed 602</h2><h3>Suggested Modes Of Care In Infants Of Different Gestational And Postnatal Ages</h3><p>Infant Group At Birth Week 1</p><small class=\"source\">PDF p. 613</small><p>Key Points</p><small class=\"source\">PDF p. 613</small><h3>• Cold Stress And/Or Hypothermia Negatively Impact Vital</h3><p>neonatal outcomes such as survival and growth.</p><small class=\"source\">PDF p. 613</small><h3>• Heat Exchange Between The Infant And The Care Environ-</h3><p>ment occurs through convection, radiation, evaporation, and conduction. Their relative contributions and the direction of heat transfer depend on infant maturity, postnatal age, and mode of care.</p><small class=\"source\">PDF p. 613</small><h3>• Thermal (And Fluid) Management Of The Extremely</h3><p>preterm infant is simplified by use of a high humidity micro-environment during the first week(s) of life. This</p><small class=\"source\">PDF p. 613</small><h3>References</h3><p>1. Silverman WA, Fertig JW, Berger AP. The influence of the ther-</p><small class=\"source\">PDF p. 613</small><p>mal environment upon the survival of newly born premature infants. Pediatrics. 1958;22(5):876–886. 2. Moore ER, Bergman N, Anderson GC, Medley N. Early skin-</p><small class=\"source\">PDF p. 613</small><p>to-skin contact for mothers and their healthy newborn infants. Cochrane Database Syst Rev. 2016;11:CD003519. https://doi. org/10.1002/14651858.CD003519.pub4. 3. McCall EM, Alderdice F, Halliday HL, et al. Interventions to</p><small class=\"source\">PDF p. 613</small><p>prevent hypothermia at birth in preterm and/or low birth weight infants. Cochrane Database Syst Rev. 2018;2:CD004210. https:// doi.org/10.1002/14651858.CD004210.pub5. 4. Lunze K, Bloom DE, Jamison DT, Hamer DH. The global bur-</p><small class=\"source\">PDF p. 613</small><p>den of neonatal hypothermia: systematic review of a major challenge for newborn survival. BMC Med. 2013;11:24. https://doi. org/10.1186/1741-7015-11-24. 5. Hey EN, Katz G. Evaporative water loss in the new-born baby.</p><small class=\"source\">PDF p. 613</small><p>J Physiol. 1969;200(3):605–619. https://doi.org/10.1113/ jphysiol.1969.sp008711. 6. te Pas AB, Lopriore E, Dito I, Morley CJ, Walther FJ. Humidi-</p><small class=\"source\">PDF p. 613</small><p>fied and heated air during stabilization at birth improves temperature in preterm infants. Pediatrics. 2010;125(6):e1427–e1432. https://doi.org/10.1542/peds.2009-2656.</p><small class=\"source\">PDF p. 613</small><p>Weeks 2–4</p><small class=\"source\">PDF p. 613</small><p>can be accomplished in a highly humidified incubator, by use of plastic dressings under a radiant warmer, or by appropriately conducted SSC.</p><small class=\"source\">PDF p. 613</small><h3>• Thermal Care Benefits From A Protocol-Driven Approach</h3><p>using guidelines that minimize variation in practice. They should specify in which situations incubators, radiant warmers, heated mattresses, and SSCs should be used, and how to monitor body temperature and what temperature to aim for.</p><small class=\"source\">PDF p. 613</small><p>7. Reed RC, Johnson DE, Nie AM. Preterm infant skin structure</p><small class=\"source\">PDF p. 613</small><p>is qualitatively and quantitatively different from that of term newborns. Pediatr Dev Pathol. 2021;24(2):96–102. https://doi. org/10.1177/1093526620976831. 8. Hammarlund K, Sedin G. Transepidermal water loss in new-</p><small class=\"source\">PDF p. 613</small><p>born infants. III. Relation to gestational age. Acta Paediatr Scand. 1979;68(6):795–801. https://doi.org/10.1111/j.1651-2227. 1979.tb08214.x. 9. Agren J, Sjors G, Sedin G. Transepidermal water loss in infants born</p><small class=\"source\">PDF p. 613</small><p>at 24 and 25 weeks of gestation. Acta Paediatr. 1998;87(11):1185– 1190. https://doi.org/10.1080/080352598750031194. 10. Agren J, Segar JL, Soderstrom F, Bell EF. Fluid management</p><small class=\"source\">PDF p. 613</small><p>considerations in extremely preterm infants born at 22-24 weeks of gestation. Semin Perinatol. 2022;46(1):151541. https://doi. org/10.1016/j.semperi.2021.151541. 11. Hammarlund K, Stromberg B, Sedin G. Heat loss from the</p><small class=\"source\">PDF p. 613</small><p>skin of preterm and fullterm newborn infants during the first weeks after birth. Biol Neonate. 1986;50(1):1–10. https://doi. org/10.1159/000242554. 12. Sedin G, Hammarlund K, Stromberg B. Transepidermal water loss in</p><small class=\"source\">PDF p. 613</small><p>full-term and pre-term infants. Acta Paediatr Scand Suppl. 1983; 305:27–31. https://doi.org/10.1111/j.1651-2227.1983.tb09855.x. 13. Power GG. Biology of temperature: the mammalian fetus. J Dev</p><small class=\"source\">PDF p. 613</small><p>Physiol. 1989;12(6):295–304.</p><small class=\"source\">PDF p. 613</small><figure class=\"source-page\"><a href=\"tables/ch035_page0613.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch035_page0613.jpg\" alt=\"Original source page 613, including its figures or tables\"></a><figcaption>Original source-page view · PDF 613. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"614\"><h2>PDF page 614 · Printed 603</h2><h3>• Thermal Care Benefits From A Protocol-Driven Approach</h3><p>14. Hey EN. The relation between environmental temperature</p><small class=\"source\">PDF p. 614</small><p>and oxygen consumption in the new-born baby. J Physiol. 1969;200(3):589–603. https://doi.org/10.1113/jphysiol.1969. sp008710. 15. Hey EN, Katz G. The optimum thermal environment for naked</p><small class=\"source\">PDF p. 614</small><p>babies. Arch Dis Child. 1970;45(241):328–334. https://doi. org/10.1136/adc.45.241.328. 16. Ko HK, Flemmer A, Haberl C, Simbruner G. Methodologi-</p><small class=\"source\">PDF p. 614</small><p>cal investigation of measuring nasopharyngeal temperature as noninvasive brain temperature analogue in the neonate. Intensive Care Med. 2001;27(4):736–742. https://doi.org/10.1007/ s001340000829. 17. Morley CJ, Hewson PH, Thornton AJ, Cole TJ. Axillary and</p><small class=\"source\">PDF p. 614</small><p>rectal temperature measurements in infants. Arch Dis Child. 1992;67(1):122–125. https://doi.org/10.1136/adc.67.1.122. 18. Baumgart S, Costarino AT. Water and electrolyte metabolism of</p><small class=\"source\">PDF p. 614</small><p>the micropremie. Clin Perinatol. 2000;27(1):131–146. https:// doi.org/10.1016/s0095-5108(05)70010-5. vi-vii. 19. Ussat M, Vogtmann C, Gebauer C, et al. The role of elevated</p><small class=\"source\">PDF p. 614</small><p>central-peripheral temperature difference in early detection of late-onset sepsis in preterm infants. Early Hum Dev. 2015;91(12):677–681. https://doi.org/10.1016/j.earlhumdev.2015.09.007. 20. Lyon AJ, Pikaar ME, Badger P, McIntosh N. Temperature con-</p><small class=\"source\">PDF p. 614</small><p>trol in very low birthweight infants during first five days of life. Arch Dis Child Fetal Neonatal Ed. 1997;76(1):F47–F50. https:// doi.org/10.1136/fn.76.1.f47. 21. Thomas KA, Burr R. Preterm infant thermal care: differing</p><small class=\"source\">PDF p. 614</small><p>thermal environments produced by air versus skin servo-control incubators. J Perinatol. 1999;19(4):264–270. https://doi. org/10.1038/sj.jp.7200183. 22. Erbani R, Degrugilliers L, Lahana A, et al. Failing to meet rela-</p><small class=\"source\">PDF p. 614</small><p>tive humidity targets for incubated neonates causes higher heat loss and metabolic costs in the first week of life. Acta Paediatr. 2018;107(7):1177–1183. https://doi.org/10.1111/apa.14063. 23. Sherman TI, Greenspan JS, St Clair N, et al. Optimizing the</p><small class=\"source\">PDF p. 614</small><p>neonatal thermal environment. Neonatal Netw. 2006;25(4):251– 260. https://doi.org/10.1891/0730-0832.25.4.251. 24. Hanley K, Jiang Y, Elias PM, et al. Acceleration of barrier ontogen-</p><small class=\"source\">PDF p. 614</small><p>esis in vitro through air exposure. Pediatr Res. 1997;41(2):293– 299. https://doi.org/10.1203/00006450-199702000-00022. 25. Agren J, Sjors G, Sedin G. Ambient humidity influences the</p><small class=\"source\">PDF p. 614</small><p>rate of skin barrier maturation in extremely preterm infants. J Pediatr. 2006;148(5):613–617. https://doi.org/10.1016/j. jpeds.2005.11.027. 26. Flenady VJ, Woodgate PG. Radiant warmers versus incuba-</p><small class=\"source\">PDF p. 614</small><p>tors for regulating body temperature in newborn infants. Cochrane Database Syst Rev. 2003;4:CD000435. https://doi. org/10.1002/14651858.CD000435.</p><small class=\"source\">PDF p. 614</small><p>27. Kim SM, Lee EY, Chen J, Ringer SA. Improved care and growth</p><small class=\"source\">PDF p. 614</small><p>outcomes by using hybrid humidified incubators in very preterm infants. Pediatrics. 2010;125(1):e137–e145. https://doi. org/10.1542/peds.2008-2997. 28. Conde-Agudelo A, Diaz-Rossello JL. Kangaroo mother care</p><small class=\"source\">PDF p. 614</small><p>to reduce morbidity and mortality in low birthweight infants. Cochrane Database Syst Rev. Aug 23 2016;(8):CD002771. https://doi.org/10.1002/14651858.CD002771.pub4. 29. Nyqvist KH, Anderson GC, Bergman N, et al. State of the art</p><small class=\"source\">PDF p. 614</small><p>and recommendations. Kangaroo mother care: application in a high-tech environment. Acta Paediatr. 2010;99(6):812–819. https://doi.org/10.1111/j.1651-2227.2010.01794.x. 30. Thernstrom Blomqvist Y, Agren J, Karlsson V. The Swedish</p><small class=\"source\">PDF p. 614</small><p>approach to nurturing extremely preterm infants and their families: a nursing perspective. Semin Perinatol. 2022;46(1):151542. https://doi.org/10.1016/j.semperi.2021.151542. 31. Bauer K, Pyper A, Sperling P, et al. Effects of gestational and post-</p><small class=\"source\">PDF p. 614</small><p>natal age on body temperature, oxygen consumption, and activity during early skin-to-skin contact between preterm infants of 25-30week gestation and their mothers. Pediatr Res. 1998;44(2):247– 251. https://doi.org/10.1203/00006450-199808000-00018. 32. Bauer K, Uhrig C, Sperling P, et al. Body temperatures and</p><small class=\"source\">PDF p. 614</small><p>oxygen consumption during skin-to-skin (kangaroo) care in stable preterm infants weighing less than 1500 grams. J Pediatr. 1997;130(2):240–244. https://doi.org/10.1016/s0022- 3476(97)70349-4. 33. Maastrup R, Greisen G. Extremely preterm infants tolerate</p><small class=\"source\">PDF p. 614</small><p>skin-to-skin contact during the first weeks of life. Acta Paediatr. 2010;99(8):1145–1149. https://doi.org/10.1111/j.1651- 2227.2010.01806.x. 34. Karlsson V, Heinemann AB, Sjors G, et al. Early skin-to-skin</p><small class=\"source\">PDF p. 614</small><p>care in extremely preterm infants: thermal balance and care environment. J Pediatr. 2012;161(3):422–426. https://doi. org/10.1016/j.jpeds.2012.02.034. 35. Gray PH, Flenady V. Cot-nursing versus incubator care for pre-</p><small class=\"source\">PDF p. 614</small><p>term infants. Cochrane Database Syst Rev. 2011;8:CD003062. https://doi.org/10.1002/14651858.CD003062.pub2. 36. Maayan-Metzger A, Yosipovitch G, Hadad E, Sirota L. Transepi-</p><small class=\"source\">PDF p. 614</small><p>dermal water loss and skin hydration in preterm infants during phototherapy. Am J Perinatol. 2001;18(7):393–396. https://doi. org/10.1055/s-2001-18698. 37. Pezzati M, Fusi F, Dani C, et al. Changes in skin temperature of</p><small class=\"source\">PDF p. 614</small><p>hyperbilirubinemic newborns under phototherapy: conventional versus fiberoptic device. Am J Perinatol. 2002;19(8):439–444. https://doi.org/10.1055/s-2002-36839. 38. New K, Flenady V, Davies MW. Transfer of preterm infants</p><small class=\"source\">PDF p. 614</small><p>from incubator to open cot at lower versus higher body weight. Cochrane Database Syst Rev. 2011;9:CD004214. https://doi. org/10.1002/14651858.CD004214.pub4.</p><small class=\"source\">PDF p. 614</small></section>", "guided": {"num": 35, "title": "Thermal Environment of the Intensive Care Nursery", "hook": "Preventing heat loss requires understanding the environment as well as measuring the infant.", "audience": "Pediatric residents, neonatal fellows and clinicians studying the source edition", "prerequisites": "Core neonatal physiology and clinical assessment; foundational chapters support entry-level review.", "estimated_minutes": 25, "estimated_minutes_note": "Planning estimate for five units and feedback; full reference reading takes longer.", "lessons": [{"id": "L035-1", "objective_id": "O035-1", "objective": "List the four physical modes of heat exchange", "title": "Heat-exchange modes", "level": "Essentials", "text": "Convection, radiation, evaporation and conduction. All four heat-exchange modes vary with maturity, environment and postnatal age.", "card_id": "fc-035-1", "question_id": "q-035-1", "pdf_page": 605, "printed_page": "594"}, {"id": "L035-2", "objective_id": "O035-2", "objective": "Explain high evaporative loss in extreme prematurity", "title": "Immature skin", "level": "Clinical Application", "text": "An immature skin barrier. Skin barrier competence develops with maturity, so very immature infants have much higher transepidermal water and heat loss.", "card_id": "fc-035-2", "question_id": "q-035-2", "pdf_page": 605, "printed_page": "594"}, {"id": "L035-3", "objective_id": "O035-3", "objective": "Distinguish normal temperature from minimum metabolic cost", "title": "Thermoneutrality", "level": "Deep Dive", "text": "The range allowing normal temperature at minimal metabolic rate using nonevaporative adjustments. Thermoneutrality includes metabolic efficiency; a normal temperature alone does not prove it.", "card_id": "fc-035-3", "question_id": "q-035-3", "pdf_page": 607, "printed_page": "596"}, {"id": "L035-4", "objective_id": "O035-4", "objective": "Explain how incubator humidity affects thermal care", "title": "Humidity and evaporation", "level": "Clinical Application", "text": "Increase appropriate incubator humidity. Higher humidity lowers evaporative loss and can aid fluid and heat balance in very immature infants.", "card_id": "fc-035-4", "question_id": "q-035-4", "pdf_page": 610, "printed_page": "599"}, {"id": "L035-5", "objective_id": "O035-5", "objective": "Recognize a hazard of detached skin probes", "title": "Servo-control failure", "level": "Clinical Application", "text": "Overwarming from inappropriate heat delivery. A detached probe can lead to overwarming; device readings must be interpreted alongside infant assessment.", "card_id": "fc-035-5", "question_id": "q-035-5", "pdf_page": 610, "printed_page": "599"}], "unavailable_levels": [], "review_status": "Model checked selected cited source passages; not specialist review", "case": {"id": "case-035", "intro": "Fictional teaching scenario: an extremely preterm infant requires individualized incubator care.", "stages": [{"information": "During the first postnatal days, a very immature infant has high transepidermal water loss.", "prompt": "Which mechanism best explains the vulnerability?", "options": ["A fully keratinized impermeable skin", "An immature skin barrier", "A requirement for visible sweating", "Abundant insulating subcutaneous fat"], "answer": 1, "feedback": "Skin immaturity permits large evaporative water and heat losses.", "pdf_page": 605}, {"information": "The team reviews environmental measures to reduce the evaporative component while monitoring fluid balance.", "prompt": "Which measure directly reduces the evaporation gradient?", "options": ["Appropriate incubator humidification", "Completely drying the incubator air", "Deliberately maintaining condensation on the walls", "Ignoring ambient humidity"], "answer": 0, "feedback": "Humidity reduces evaporative loss; condensation is undesirable because it increases infection concerns.", "pdf_page": 610}, {"information": "Later the skin-servo probe is found detached and the infant feels unusually warm.", "prompt": "Which explanation requires immediate evaluation?", "options": ["Servo-control-related overwarming", "A normal probe reading proving a safe core temperature", "Guaranteed thermal neutrality", "Proof of infection from touch alone"], "answer": 0, "feedback": "Probe detachment can cause inappropriate warming. Assess the infant’s temperature and equipment rather than interpreting the display alone.", "pdf_page": 610}], "debrief": "Identify the heat-loss route, use targeted environmental support and monitor both patient and device. The case does not prescribe one humidity or temperature setting for all infants."}}});
